"""
Core data model for the Fleet Retrofit Tracker.

Kept deliberately simple. Two tables, one classification function, observations
flow in from collectors, the dashboard reads aggregates out.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from enum import Enum
from typing import Optional


class CabinState(str, Enum):
    ORIGINAL = "original"
    RETROFIT = "retrofit"
    IN_PROGRESS = "in_progress"
    UNKNOWN = "unknown"


class ObservationSource(str, Enum):
    PLANESPOTTERS = "planespotters"
    AIRLINE_PRESS = "airline_press"
    SEATMAP = "seatmap"
    HANGAR_ROUTING = "hangar_routing"
    MANUAL = "manual"


class StateSignal(str, Enum):
    ORIGINAL = "original"
    RETROFIT = "retrofit"
    IN_HANGAR = "in_hangar"


@dataclass(frozen=True)
class Aircraft:
    tail_number: str
    airline: str
    aircraft_type: str
    sub_fleet: str
    delivered: Optional[datetime] = None


@dataclass(frozen=True)
class Observation:
    tail_number: str
    observed_at: datetime
    source: ObservationSource
    source_url: str
    state_signal: StateSignal
    confidence: float
    notes: str = ""


# Confidence thresholds. Tuned conservatively because false positives erode
# credibility faster than coverage gaps do.
HIGH_CONFIDENCE = 0.8
RETROFIT_FRESHNESS = timedelta(days=90)
HANGAR_DWELL_FOR_LIKELY = timedelta(days=7)
STALE_AFTER = timedelta(days=180)


def classify(
    aircraft: Aircraft,
    observations: list[Observation],
    now: Optional[datetime] = None,
) -> CabinState:
    """Decide the current cabin state for one tail number.

    Rules, in priority order:
      1. Recent high-confidence retrofit signal -> RETROFIT.
      2. Sustained hangar dwell at a retrofit facility, no contradicting
         original sighting after -> IN_PROGRESS.
      3. Most recent observation is an original-cabin signal -> ORIGINAL.
      4. No observations in the last 180 days -> UNKNOWN.
    """
    now = now or datetime.now(timezone.utc)
    if not observations:
        return CabinState.UNKNOWN

    obs = sorted(observations, key=lambda o: o.observed_at, reverse=True)

    # Rule 1: confirmed retrofit
    for o in obs:
        if (
            o.state_signal == StateSignal.RETROFIT
            and o.confidence >= HIGH_CONFIDENCE
            and (now - o.observed_at) <= RETROFIT_FRESHNESS
        ):
            return CabinState.RETROFIT

    # Rule 2: in progress (hangar dwell with no later "original" sighting)
    hangar_obs = [o for o in obs if o.state_signal == StateSignal.IN_HANGAR]
    if hangar_obs:
        latest_hangar = hangar_obs[0]
        dwell_signals = [
            o for o in hangar_obs
            if (latest_hangar.observed_at - o.observed_at) <= HANGAR_DWELL_FOR_LIKELY
        ]
        later_original = [
            o for o in obs
            if o.state_signal == StateSignal.ORIGINAL
            and o.observed_at > latest_hangar.observed_at
        ]
        if len(dwell_signals) >= 2 and not later_original:
            return CabinState.IN_PROGRESS

    # Rule 3: most recent signal is original
    most_recent = obs[0]
    if (now - most_recent.observed_at) <= STALE_AFTER:
        if most_recent.state_signal == StateSignal.ORIGINAL:
            return CabinState.ORIGINAL

    # Rule 4: stale or contradictory
    return CabinState.UNKNOWN


def install_rate(
    retrofit_dates: list[datetime],
    window: timedelta = timedelta(days=60),
    now: Optional[datetime] = None,
) -> float:
    """Aircraft retrofitted per month, averaged over the trailing window."""
    now = now or datetime.now(timezone.utc)
    cutoff = now - window
    recent = [d for d in retrofit_dates if d >= cutoff]
    days = window.total_seconds() / 86400
    return (len(recent) / days) * 30 if days > 0 else 0.0


def project_completion(
    completed: int,
    total: int,
    rate_per_month: float,
    now: Optional[datetime] = None,
) -> Optional[datetime]:
    """Naive linear projection. Real rollouts aren't linear, but this
    is the chart that makes people pay attention to the gap between
    'announced completion' and 'reality at current rate'."""
    if rate_per_month <= 0 or completed >= total:
        return None
    now = now or datetime.now(timezone.utc)
    remaining_months = (total - completed) / rate_per_month
    return now + timedelta(days=remaining_months * 30)
